appearances.css:
.app{gap:4px;font-size:9px}
.secs{display:flex!important;flex-wrap:wrap;gap:4px}
.sec{padding:3px 4px 4px;gap:3px 0;grid-template-columns:repeat(auto-fill,minmax(39px,1fr));align-content:start;border-radius:3px;min-width:0}
.sec h4{grid-column:1/-1;font-size:8px;letter-spacing:.14em;margin:0;padding:0 0 2px}
.sec:nth-child(1){order:1;flex:8 1 320px}
.sec:nth-child(2){order:4;flex:7 1 281px}
.sec:nth-child(3){order:5;flex:5 1 203px}
.sec:nth-child(4){order:2;flex:1 1 47px}
.sec:nth-child(6){order:3;flex:1 1 47px}
.sec:nth-child(5){order:6;flex:6 1 242px}
.k,.k[style]{display:grid!important;grid-template-columns:minmax(0,1fr)!important;justify-items:center;align-items:start;gap:0;min-width:0}
.k label{order:3;font-size:7.5px;letter-spacing:-.03em;text-align:center;max-width:100%;line-height:1.1;white-space:normal;overflow:visible;text-overflow:clip;text-transform:none}
.k output{order:2;font-size:8px;text-align:center;line-height:1.1;color:var(--a-muted);white-space:nowrap}
.k .kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.k .kn svg{width:100%;height:100%}
.k select{order:1;width:100%;font-size:8px;padding:3px 0;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none;border-radius:3px;cursor:pointer}
.k:has(select) label{order:2}
.seqbox{padding:3px 5px 4px;gap:2px 6px;border-radius:3px;display:flex;flex-wrap:wrap;align-items:center}
.head{display:contents}
.head h3{display:none}
.head label{font-size:8px;order:0}
.head .k,.head .k[style]{display:flex!important;flex-direction:row;gap:3px;align-items:center;order:0}
.head .k label{order:0;font-size:8px}
.head .k select{width:auto;padding:1px 3px}
.bars{gap:2px;order:1;flex:1 1 auto}
.bars button{font-size:9px;padding:0 4px;min-width:20px;height:16px;line-height:14px}
.roll{overflow:hidden;order:2;flex:1 1 100%}
table{min-width:0;border-spacing:2px 1px;width:100%}
td{padding:0}
th{width:30px;font-size:8px;line-height:1;padding:0 2px 0 0}
.st{height:10px}
select.oc{height:11px;font-size:8px;padding:0;appearance:none;-webkit-appearance:none}
.lib{display:contents}
.lib button,.lib select{order:3;font-size:7.5px;padding:2px 2px;letter-spacing:0}
.lib select{padding:1px 0;max-width:76px}
